rss.channel:
  {{ site.title }}
  {{ base }}

  {{ site.subtitle }}
  en-us
{% for a in items %}


  {% if a.kind == "entity" %}
    New entry: {{ a.entity.entry.common_name }}
    {{ base }}{{ a.entity.url }}
    ghostlight-{{ a.entity.id }}
    {{ a.entity.entry.description }}
  {% else %}
    Sighting: {{ a.entity.entry.common_name }}, {{ voices[a.s.voice].label }} of {{ a.s.year }}
    {{ base }}{{ a.entity.url }}#{{ a.s.id }}
    ghostlight-{{ a.s.id }}
    {{ a.s.text }}
  {% endif %}
    {{ rfc822(a.date) }}

{% endfor %}
